{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "KNI-272 absolute oral bioavailability was 54.97 ± 19.78% in fasting patients after a 10 mg/kg oral capsule, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Atazanavir absolute oral bioavailability in humans was 68% (57–80%), supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Alvimopan absolute oral bioavailability in humans was estimated at only 6%, arguing against F ≥ 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer positive records with absolute F values ≥20% (KNI-272, atazanavir, sulpiride/levosulpiride, darunavir, encainide, finasteride) outweigh the lower-transfer negative records (alvimopan, ergotamine). Provenance-conflicted records were discounted.",
  "evidence_gaps": [
    "Molecule 5 groups records for different compounds (abacavir vs amprenavir), so those cards were discounted due to provenance conflict.",
    "Some records are qualitative or from altered conditions (e.g., darunavir with ritonavir, encainide in cirrhosis); numeric ordinary-condition records were prioritized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

